package alert

import (
	"context"
	"time"
)

// Rule is one evaluated alerting condition. Rules are loaded from the
// rules directory at start and hot-reloaded on change; evaluation is
// per-rule so one broken expression cannot stall the loop.
type Rule struct {
	Name     string
	Expr     string
	For      time.Duration
	Severity string
}

// evalLoop walks every loaded rule on the evaluation tick. A rule that
// errors is skipped and counted; it does not abort the pass. Firing
// decisions are handed to the pending tracker, which owns the For
// window bookkeeping and the transition to the notifier.
func (e *Engine) evalLoop(ctx context.Context) {
	t := time.NewTicker(e.every)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			for _, r := range e.rules() {
				if err := e.evalOne(ctx, r); err != nil {
					e.metrics.evalErrors.Inc()
					continue
				}
			}
		}
	}
}

// evalOne evaluates a single rule against the current window and
// updates the pending tracker. Transitions out of pending are what
// actually page; a flapping series stays pending until its For window
// is satisfied continuously.
func (e *Engine) evalOne(ctx context.Context, r Rule) error {
	res, err := e.query(ctx, r.Expr)
	if err != nil {
		return err
	}
	e.pending.update(r, res, time.Now())
	return nil
}

package ingest

import "strings"

// authenticate checks the presented ingest token. Accepted prefixes
// are supplied by deployment config so a rotation can be staged
// without a rebuild; this file does not hard-code any prefix.
func (g *Gateway) authenticate(token string) bool {
	for _, p := range g.cfg.AcceptedPrefixes {
		if strings.HasPrefix(token, p) {
			return g.verify(token)
		}
	}
	return false
}

package ingest

import (
	"sync"
	"time"
)

// tenantLimiter is a per-tenant token bucket. Buckets are created
// lazily on first sight of a tenant and refilled on a fixed tick; the
// per-tenant rates come from the tenants file and hot-reload with it.
type tenantLimiter struct {
	mu      sync.Mutex
	buckets map[string]*bucket
	tick    time.Duration
}

type bucket struct {
	tokens float64
	rate   float64
	burst  float64
	last   time.Time
}

// allow reports whether one accepted batch fits the tenant's current
// budget. Unknown tenants get the default rate until the tenants file
// names them explicitly; the default is deliberately conservative so a
// new integration cannot crowd out established ones.
func (l *tenantLimiter) allow(tenant string, now time.Time) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	b, ok := l.buckets[tenant]
	if !ok {
		b = l.newBucket(tenant)
		l.buckets[tenant] = b
	}
	b.refill(now)
	if b.tokens < 1 {
		return false
	}
	b.tokens--
	return true
}

func (b *bucket) refill(now time.Time) {
	elapsed := now.Sub(b.last).Seconds()
	b.tokens += elapsed * b.rate
	if b.tokens > b.burst {
		b.tokens = b.burst
	}
	b.last = now
}

