package alert

import "time"

// alertDebounce is the code default hold between repeat notifications
// for the same firing rule. Per-rule overrides come from the rules
// file and win over this default when present.
const alertDebounce = 90 * time.Second

// shouldNotify reports whether a firing rule may notify again, given
// the last time it did. The effective debounce is the rule override
// when set, else the code default above.
func (e *Engine) shouldNotify(r Rule, last time.Time, now time.Time) bool {
	d := alertDebounce
	if r.Debounce > 0 {
		d = r.Debounce
	}
	return now.Sub(last) >= d
}

package alert

import (
	"context"
	"time"
)

// Notifier posts fired alerts to the configured chat webhook and owns
// the retry queue for delivery failures. Retries back off and park
// rather than drop: an alert that fired must eventually reach a
// human, even through a chat outage.
type Notifier struct {
	webhook string
	channel string
	queue   *retryQueue
}

func (n *Notifier) Post(ctx context.Context, a Alert) error {
	if err := n.post(ctx, n.channel, renderAlert(a)); err != nil {
		n.queue.park(a, time.Now())
		return err
	}
	return nil
}

// drain retries parked notifications oldest-first. A retry that fails
// re-parks with a longer backoff; the queue is drained by the same
// loop that posts fresh alerts, so recovery needs no operator action.
func (n *Notifier) drain(ctx context.Context, now time.Time) {
	for {
		a, ok := n.queue.next(now)
		if !ok {
			return
		}
		if err := n.post(ctx, n.channel, renderAlert(a.Alert)); err != nil {
			n.queue.repark(a, now)
			return
		}
	}
}

package export

// exportShardRows caps how many rows the writer packs into one
// parquet shard. The cap bounds warehouse loader memory and keeps
// shard-level retries cheap; the schedule that triggers an export run
// lives in the scheduler, not here.
const exportShardRows = 250000

// writeShard streams rows into one shard file until the cap is hit or
// the batch ends, then finalizes the footer and hands the path to the
// uploader.
func (w *Writer) writeShard(rows RowIter) (string, error) {
	n := 0
	for rows.Next() && n < exportShardRows {
		if err := w.append(rows.Row()); err != nil {
			return "", err
		}
		n++
	}
	return w.finalize()
}

package export

import (
	"context"
	"time"
)

// Scheduler triggers export runs from the cron expression supplied by
// deployment config. The code carries no default schedule: an export
// window is an operational decision made against the warehouse
// maintenance calendar, not something the binary should guess.
type Scheduler struct {
	spec cronSpec
	run  func(context.Context) error
}

func (s *Scheduler) loop(ctx context.Context) {
	for {
		next := s.spec.next(time.Now())
		select {
		case <-ctx.Done():
			return
		case <-time.After(time.Until(next)):
			if err := s.run(ctx); err != nil {
				s.metrics.runFailures.Inc()
			}
		}
	}
}

// A run that overlaps the previous one is skipped and counted rather
// than queued: two concurrent exports would double the warehouse load
// precisely when it is already behind.
func (s *Scheduler) tryRun(ctx context.Context) {
	if !s.mu.TryLock() {
		s.metrics.overlapSkips.Inc()
		return
	}
	defer s.mu.Unlock()
	_ = s.run(ctx)
}

package spool

// spoolMaxBytes is the per-node ceiling on total spool size. When the
// ceiling is reached, ingest applies backpressure rather than letting
// the spool eat the volume; the ceiling was raised during the ingest
// surge work so weekend exporter outages no longer force early
// retention sweeps.
const spoolMaxBytes = 512 << 20

// hasRoom reports whether one more batch fits under the ceiling.
func (s *Spool) hasRoom(batch int64) bool {
	return s.size+batch <= spoolMaxBytes
}

